1	// `andesim profile [--engine <id>] [report flags] ELF [-- <qemu args>]`.
2	//
3	// Hot inner-loop detection on the FUNCTIONAL engine, configured like the
4	// hybrid fast leg: profile picks a cycle-accurate engine (--engine or the
5	// sole one, the same selector cycle/hybrid use) and derives the QEMU launch
6	// from it -- the CPU model from the engine's `--print-qemu-config` driver
7	// globals, vlen from its --describe, and the staged qemu.cfg as -readconfig.
8	// That keeps the profiled ISA identical to the engine the reported
9	// `measure: --pc-start/--pc-end` windows will be measured on (a wrong vlen
10	// changes vsetvl trip counts, i.e. the hot-loop ranking itself).
11	//
12	// QEMU runs the ELF to completion with the hotIterationLoop TCG plugin; the
13	// plugin's
14	// `-d plugin -D` log is parsed, filtered (min-iters, RVV-only), nested, and
15	// rendered as the LLM Markdown report (or --no-llm table). All pure logic
16	// lives in profile.cpp; this file owns the IO: engine resolve, the cfg probe,
17	// the QEMU spawn, objdump/addr2line, and the per-loop symbol lookups.
18	#include <sys/wait.h>
19	#include <unistd.h>
20	
21	#include <algorithm>
22	#include <cstdint>
23	#include <cstdio>
24	#include <cstdlib>
25	#include <filesystem>
26	#include <fstream>
27	#include <map>
28	#include <sstream>
29	#include <string>
30	#include <vector>
31	
32	#include "argv.hpp"
33	#include "cli.hpp"
34	#include "config_env.hpp"
35	#include "elf_syms.hpp"
36	#include "engine_descriptor.hpp"
37	#include "engine_registry.hpp"
38	#include "log.hpp"
39	#include "process.hpp"
40	#include "profile.hpp"
41	#include "repo_root.hpp"
42	#include "run_plan.hpp"
43	
44	namespace fs = std::filesystem;
45	
46	namespace andes_sim {
47	namespace {
48	
49	// The bundled hot-loop plugin under the repo root (the profile counterpart of
50	// default_plugin_path's hybrid plugin).
51	fs::path profile_plugin_path() {
52	  return repo_root() / "qemu_plugin" / "libhotIterationLoop.so";
53	}
54	
55	// Does `cmd` resolve to an executable (absolute/relative path, or via PATH)?
56	bool cmd_exists(const std::string& cmd) {
57	  if (cmd.find('/') != std::string::npos)
58	    return ::access(cmd.c_str(), X_OK) == 0;
59	  const char* path_env = std::getenv("PATH");
60	  if (!path_env) return false;
61	  std::istringstream ss(path_env);
62	  std::string dir;
63	  while (std::getline(ss, dir, ':'))
64	    if (!dir.empty() && ::access((dir + "/" + cmd).c_str(), X_OK) == 0)
65	      return true;
66	  return false;
67	}
68	
69	std::string find_first(const std::vector<std::string>& cands) {
70	  for (const auto& c : cands)
71	    if (cmd_exists(c)) return c;
72	  return "";
73	}
74	
75	// The cross objdump chain: --objdump wins, else $HYBRID_TOOLCHAIN (env or
76	// config.env) so RISC-V vendor extensions (RVV, Andes custom) decode
77	// correctly -- generic llvm-objdump on old distros may not know RVV.
78	std::string resolve_objdump(const std::string& override_path) {
79	  if (!override_path.empty()) return override_path;
80	  std::vector<std::string> cands;
81	  if (const std::string tc = config_env_value("HYBRID_TOOLCHAIN"); !tc.empty()) {
82	    cands.push_back(tc + "/bin/riscv64-unknown-elf-objdump");
83	    cands.push_back(tc + "/bin/riscv32-unknown-elf-objdump");
84	  }
85	  cands.insert(cands.end(), {"riscv64-unknown-elf-objdump",
86	                             "riscv32-unknown-elf-objdump", "llvm-objdump",
87	                             "objdump"});
88	  return find_first(cands);
89	}
90	
91	// Write lines to argv's stdin; capture its stdout. Used for addr2line, which
92	// takes one hex address per input line.
93	std::string capture_with_stdin(const std::vector<std::string>& argv,
94	                               const std::string& input) {
95	  if (argv.empty()) return "";
96	  int in_fds[2], out_fds[2];
97	  if (pipe(in_fds) != 0) return "";
98	  if (pipe(out_fds) != 0) {
99	    close(in_fds[0]);
100	    close(in_fds[1]);
101	    return "";
102	  }
103	  pid_t pid = fork();
104	  if (pid < 0) {
105	    close(in_fds[0]); close(in_fds[1]);
106	    close(out_fds[0]); close(out_fds[1]);
107	    return "";
108	  }
109	  if (pid == 0) {
110	    close(in_fds[1]);
111	    close(out_fds[0]);
112	    dup2(in_fds[0], STDIN_FILENO);
113	    dup2(out_fds[1], STDOUT_FILENO);
114	    if (FILE* devnull = std::fopen("/dev/null", "w"))
115	      dup2(fileno(devnull), STDERR_FILENO);
116	    close(in_fds[0]);
117	    close(out_fds[1]);
118	    std::vector<char*> cargv;
119	    cargv.reserve(argv.size() + 1);
120	    for (const auto& a : argv) cargv.push_back(const_cast<char*>(a.c_str()));
121	    cargv.push_back(nullptr);
122	    execvp(cargv[0], cargv.data());
123	    _exit(127);
124	  }
125	  close(in_fds[0]);
126	  close(out_fds[1]);
127	  const char* p = input.data();
128	  size_t rem = input.size();
129	  while (rem > 0) {
130	    ssize_t w = write(in_fds[1], p, rem);
131	    if (w < 0) break;
132	    p += w;
133	    rem -= static_cast<size_t>(w);
134	  }
135	  close(in_fds[1]);
136	  std::string out;
137	  char buf[4096];
138	  ssize_t n;
139	  while ((n = read(out_fds[0], buf, sizeof(buf))) > 0)
140	    out.append(buf, static_cast<size_t>(n));
141	  close(out_fds[0]);
142	  int status = 0;
143	  waitpid(pid, &status, 0);
144	  return out;
145	}
146	
147	// addr2line every pc in `pcs` against `elf_path`; unknown ("??") lines drop
148	// out, so absent keys mean "no source info".
149	std::map<uint64_t, std::string> resolve_sources(
150	    const std::string& addr2line_bin, const std::string& elf_path,
151	    const std::vector<uint64_t>& pcs) {
152	  std::map<uint64_t, std::string> result;
153	  if (addr2line_bin.empty() || pcs.empty()) return result;
154	  std::string input;
155	  for (uint64_t pc : pcs) {
156	    char buf[20];
157	    std::snprintf(buf, sizeof(buf), "0x%llx\n", (unsigned long long)pc);
158	    input += buf;
159	  }
160	  const std::string out =
161	      capture_with_stdin({addr2line_bin, "-e", elf_path}, input);
162	  std::istringstream ss(out);
163	  std::string line;
164	  size_t idx = 0;
165	  while (std::getline(ss, line) && idx < pcs.size()) {
166	    while (!line.empty() && (line.back() == '\r' || line.back() == '\n'))
167	      line.pop_back();
168	    if (!line.empty() && line.find("??") == std::string::npos)
169	      result[pcs[idx]] = line;
170	    ++idx;
171	  }
172	  return result;
173	}
174	
175	// The trimmed text of `path`'s line `lineno` ("" when unreadable).
176	std::string read_source_line(const std::string& path, int lineno) {
177	  if (path.empty() || lineno <= 0 || !fs::is_regular_file(path)) return "";
178	  std::ifstream f(path);
179	  std::string line;
180	  for (int i = 1; std::getline(f, line); ++i) {
181	    if (i != lineno) continue;
182	    while (!line.empty() && (line.back() == '\r' || line.back() == '\n' ||
183	                             line.back() == ' ' || line.back() == '\t'))
184	      line.pop_back();
185	    auto s = line.find_first_not_of(" \t");
186	    return (s != std::string::npos) ? line.substr(s) : line;
187	  }
188	  return "";
189	}
190	
191	// Symbol lookups (delegate to elf_syms; the ELF is small and OS-page-cached).
192	std::string sym_at(const std::string& elf, uint64_t pc) {
193	  std::string s = symbolize(elf, pc);
194	  if (!s.empty()) return s;
195	  char buf[20];
196	  std::snprintf(buf, sizeof(buf), "0x%llx", (unsigned long long)pc);
197	  return buf;
198	}
199	
200	std::string sym_func_at(const std::string& elf, uint64_t pc) {
201	  std::string s = symbolize(elf, pc);
202	  auto p = s.find('+');
203	  return (p != std::string::npos) ? s.substr(0, p) : s;
204	}
205	
206	// Fill one loop's LoopSyms from the ELF + the resolved source map.
207	LoopSyms make_syms(const std::string& elf, uint64_t start, uint64_t end,
208	                   const std::map<uint64_t, std::string>& src_map) {
209	  LoopSyms s;
210	  s.sym_start = sym_at(elf, start);
211	  s.sym_end = sym_at(elf, end);
212	  s.fn_name = sym_func_at(elf, start);
213	  auto [fe, fx] = fn_range(elf, start);
214	  s.fn_entry = fe;
215	  s.fn_end = fx;
216	  if (auto it = src_map.find(start); it != src_map.end()) s.src_start = it->second;
217	  if (auto it = src_map.find(end); it != src_map.end()) s.src_end = it->second;
218	  auto [path, lineno] = parse_file_line(s.src_start);
219	  s.code_snippet = read_source_line(path, lineno);
220	  return s;
221	}
222	
223	// A "" -> `def` positive-int knob (--limit, --min-iters).
224	bool parse_knob(const std::string& v, int def, int& out) {
225	  if (v.empty()) {
226	    out = def;
227	    return true;
228	  }
229	  try {
230	    size_t pos = 0;
231	    out = std::stoi(v, &pos);
232	    return pos == v.size() && out > 0;
233	  } catch (...) {
234	    return false;
235	  }
236	}
237	
238	// mkdtemp workdir holding the staged qemu.cfg + the plugin log; removed on
239	// scope exit (the report is the product; there is nothing to keep).
240	struct Workdir {
241	  std::string path;
242	  std::string error;
243	  Workdir() {
244	    char tmpl[] = "/tmp/andesim-profile.XXXXXX";
245	    if (::mkdtemp(tmpl))
246	      path = tmpl;
247	    else
248	      error = "cannot create the profile workdir under /tmp";
249	  }
250	  ~Workdir() {
251	    if (path.empty()) return;
252	    std::error_code ec;
253	    fs::remove_all(path, ec);
254	  }
255	};
256	
257	}  // namespace
258	
259	int cmd_profile(const Cli& cli) {
260	  auto fail = [](const std::string& msg) {
261	    std::fprintf(stderr, "andesim profile: %s\n", msg.c_str());
262	    return 2;
263	  };
264	
265	  // profile is not `run`: reject run-only flags loudly instead of silently
266	  // ignoring them (a silently dropped --trigger would look like a hung ROI).
267	  {
268	    const struct {
269	      bool set;
270	      const char* flag;
271	    } runonly[] = {
272	        {!cli.model.empty(), "--mode"},
273	        {!cli.trigger.empty(), "--trigger"},
274	        {!cli.pc_start.empty(), "--pc-start"},
