// `andesim profile [--engine <id>] [report flags] ELF [-- <qemu args>]`.
//
// Hot inner-loop detection on the FUNCTIONAL engine, configured like the
// hybrid fast leg: profile picks a cycle-accurate engine (--engine or the
// sole one, the same selector cycle/hybrid use) and derives the QEMU launch
// from it -- the CPU model from the engine's `--print-qemu-config` driver
// globals, vlen from its --describe, and the staged qemu.cfg as -readconfig.
// That keeps the profiled ISA identical to the engine the reported
// `measure: --pc-start/--pc-end` windows will be measured on (a wrong vlen
// changes vsetvl trip counts, i.e. the hot-loop ranking itself).
//
// QEMU runs the ELF to completion with the hotIterationLoop TCG plugin; the
// plugin's
// `-d plugin -D` log is parsed, filtered (min-iters, RVV-only), nested, and
// rendered as the LLM Markdown report (or --no-llm table). All pure logic
// lives in profile.cpp; this file owns the IO: engine resolve, the cfg probe,
// the QEMU spawn, objdump/addr2line, and the per-loop symbol lookups.
#include <sys/wait.h>
#include <unistd.h>

#include <algorithm>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <filesystem>
#include <fstream>
#include <map>
#include <sstream>
#include <string>
#include <vector>

#include "argv.hpp"
#include "cli.hpp"
#include "config_env.hpp"
#include "elf_syms.hpp"
#include "engine_descriptor.hpp"
#include "engine_registry.hpp"
#include "log.hpp"
#include "process.hpp"
#include "profile.hpp"
#include "repo_root.hpp"
#include "run_plan.hpp"

namespace fs = std::filesystem;

namespace andes_sim {
namespace {

// The bundled hot-loop plugin under the repo root (the profile counterpart of
// default_plugin_path's hybrid plugin).
fs::path profile_plugin_path() {
  return repo_root() / "qemu_plugin" / "libhotIterationLoop.so";
}

// Does `cmd` resolve to an executable (absolute/relative path, or via PATH)?
bool cmd_exists(const std::string& cmd) {
  if (cmd.find('/') != std::string::npos)
    return ::access(cmd.c_str(), X_OK) == 0;
  const char* path_env = std::getenv("PATH");
  if (!path_env) return false;
  std::istringstream ss(path_env);
  std::string dir;
  while (std::getline(ss, dir, ':'))
    if (!dir.empty() && ::access((dir + "/" + cmd).c_str(), X_OK) == 0)
      return true;
  return false;
}

std::string find_first(const std::vector<std::string>& cands) {
  for (const auto& c : cands)
    if (cmd_exists(c)) return c;
  return "";
}

// The cross objdump chain: --objdump wins, else $HYBRID_TOOLCHAIN (env or
// config.env) so RISC-V vendor extensions (RVV, Andes custom) decode
// correctly -- generic llvm-objdump on old distros may not know RVV.
std::string resolve_objdump(const std::string& override_path) {
  if (!override_path.empty()) return override_path;
  std::vector<std::string> cands;
  if (const std::string tc = config_env_value("HYBRID_TOOLCHAIN"); !tc.empty()) {
    cands.push_back(tc + "/bin/riscv64-unknown-elf-objdump");
    cands.push_back(tc + "/bin/riscv32-unknown-elf-objdump");
  }
  cands.insert(cands.end(), {"riscv64-unknown-elf-objdump",
                             "riscv32-unknown-elf-objdump", "llvm-objdump",
                             "objdump"});
  return find_first(cands);
}

// Write lines to argv's stdin; capture its stdout. Used for addr2line, which
// takes one hex address per input line.
std::string capture_with_stdin(const std::vector<std::string>& argv,
                               const std::string& input) {
  if (argv.empty()) return "";
  int in_fds[2], out_fds[2];
  if (pipe(in_fds) != 0) return "";
  if (pipe(out_fds) != 0) {
    close(in_fds[0]);
    close(in_fds[1]);
    return "";
  }
  pid_t pid = fork();
  if (pid < 0) {
    close(in_fds[0]); close(in_fds[1]);
    close(out_fds[0]); close(out_fds[1]);
    return "";
  }
  if (pid == 0) {
    close(in_fds[1]);
    close(out_fds[0]);
    dup2(in_fds[0], STDIN_FILENO);
    dup2(out_fds[1], STDOUT_FILENO);
    if (FILE* devnull = std::fopen("/dev/null", "w"))
      dup2(fileno(devnull), STDERR_FILENO);
    close(in_fds[0]);
    close(out_fds[1]);
    std::vector<char*> cargv;
    cargv.reserve(argv.size() + 1);
    for (const auto& a : argv) cargv.push_back(const_cast<char*>(a.c_str()));
    cargv.push_back(nullptr);
    execvp(cargv[0], cargv.data());
    _exit(127);
  }
  close(in_fds[0]);
  close(out_fds[1]);
  const char* p = input.data();
  size_t rem = input.size();
  while (rem > 0) {
    ssize_t w = write(in_fds[1], p, rem);
    if (w < 0) break;
    p += w;
    rem -= static_cast<size_t>(w);
  }
  close(in_fds[1]);
  std::string out;
  char buf[4096];
  ssize_t n;
  while ((n = read(out_fds[0], buf, sizeof(buf))) > 0)
    out.append(buf, static_cast<size_t>(n));
  close(out_fds[0]);
  int status = 0;
  waitpid(pid, &status, 0);
  return out;
}

// addr2line every pc in `pcs` against `elf_path`; unknown ("??") lines drop
// out, so absent keys mean "no source info".
std::map<uint64_t, std::string> resolve_sources(
    const std::string& addr2line_bin, const std::string& elf_path,
    const std::vector<uint64_t>& pcs) {
  std::map<uint64_t, std::string> result;
  if (addr2line_bin.empty() || pcs.empty()) return result;
  std::string input;
  for (uint64_t pc : pcs) {
    char buf[20];
    std::snprintf(buf, sizeof(buf), "0x%llx\n", (unsigned long long)pc);
    input += buf;
  }
  const std::string out =
      capture_with_stdin({addr2line_bin, "-e", elf_path}, input);
  std::istringstream ss(out);
  std::string line;
  size_t idx = 0;
  while (std::getline(ss, line) && idx < pcs.size()) {
    while (!line.empty() && (line.back() == '\r' || line.back() == '\n'))
      line.pop_back();
    if (!line.empty() && line.find("??") == std::string::npos)
      result[pcs[idx]] = line;
    ++idx;
  }
  return result;
}

// The trimmed text of `path`'s line `lineno` ("" when unreadable).
std::string read_source_line(const std::string& path, int lineno) {
  if (path.empty() || lineno <= 0 || !fs::is_regular_file(path)) return "";
  std::ifstream f(path);
  std::string line;
  for (int i = 1; std::getline(f, line); ++i) {
    if (i != lineno) continue;
    while (!line.empty() && (line.back() == '\r' || line.back() == '\n' ||
                             line.back() == ' ' || line.back() == '\t'))
      line.pop_back();
    auto s = line.find_first_not_of(" \t");
    return (s != std::string::npos) ? line.substr(s) : line;
  }
  return "";
}

// Symbol lookups (delegate to elf_syms; the ELF is small and OS-page-cached).
std::string sym_at(const std::string& elf, uint64_t pc) {
  std::string s = symbolize(elf, pc);
  if (!s.empty()) return s;
  char buf[20];
  std::snprintf(buf, sizeof(buf), "0x%llx", (unsigned long long)pc);
  return buf;
}

std::string sym_func_at(const std::string& elf, uint64_t pc) {
  std::string s = symbolize(elf, pc);
  auto p = s.find('+');
  return (p != std::string::npos) ? s.substr(0, p) : s;
}

// Fill one loop's LoopSyms from the ELF + the resolved source map.
LoopSyms make_syms(const std::string& elf, uint64_t start, uint64_t end,
                   const std::map<uint64_t, std::string>& src_map) {
  LoopSyms s;
  s.sym_start = sym_at(elf, start);
  s.sym_end = sym_at(elf, end);
  s.fn_name = sym_func_at(elf, start);
  auto [fe, fx] = fn_range(elf, start);
  s.fn_entry = fe;
  s.fn_end = fx;
  if (auto it = src_map.find(start); it != src_map.end()) s.src_start = it->second;
  if (auto it = src_map.find(end); it != src_map.end()) s.src_end = it->second;
  auto [path, lineno] = parse_file_line(s.src_start);
  s.code_snippet = read_source_line(path, lineno);
  return s;
}

// A "" -> `def` positive-int knob (--limit, --min-iters).
bool parse_knob(const std::string& v, int def, int& out) {
  if (v.empty()) {
    out = def;
    return true;
  }
  try {
    size_t pos = 0;
    out = std::stoi(v, &pos);
    return pos == v.size() && out > 0;
  } catch (...) {
    return false;
  }
}

// mkdtemp workdir holding the staged qemu.cfg + the plugin log; removed on
// scope exit (the report is the product; there is nothing to keep).
struct Workdir {
  std::string path;
  std::string error;
  Workdir() {
    char tmpl[] = "/tmp/andesim-profile.XXXXXX";
    if (::mkdtemp(tmpl))
      path = tmpl;
    else
      error = "cannot create the profile workdir under /tmp";
  }
  ~Workdir() {
    if (path.empty()) return;
    std::error_code ec;
    fs::remove_all(path, ec);
  }
};

}  // namespace

int cmd_profile(const Cli& cli) {
  auto fail = [](const std::string& msg) {
    std::fprintf(stderr, "andesim profile: %s\n", msg.c_str());
    return 2;
  };

  // profile is not `run`: reject run-only flags loudly instead of silently
  // ignoring them (a silently dropped --trigger would look like a hung ROI).
  {
    const struct {
      bool set;
      const char* flag;
    } runonly[] = {
        {!cli.model.empty(), "--mode"},
        {!cli.trigger.empty(), "--trigger"},
        {!cli.pc_start.empty(), "--pc-start"},
        {!cli.pc_end.empty(), "--pc-end"},
        {cli.verify, "--verify"},
        {!cli.kanata.empty(), "--kanata"},
        {cli.gdb, "--gdb"},
        {!cli.gdb_port.empty(), "--gdb-port"},
        {cli.print_memmap, "--print-memmap"},
    };
    for (const auto& r : runonly)
      if (r.set)
        return fail(std::string(r.flag) +
                    " is not a profile option (profile runs the whole "
                    "program under QEMU; see 'andesim profile --help')");
  }

  if (cli.positional.empty())
    return fail("missing ELF (the workload to profile)");
  if (cli.positional.size() > 1)
    return fail("unexpected argument '" + cli.positional[1] +
                "' (extra QEMU args go after --)");

  int limit = 0, min_iters = 0;
  if (!parse_knob(cli.limit, 50, limit))
    return fail("--limit must be a positive integer, got '" + cli.limit + "'");
  if (!parse_knob(cli.min_iters, 1, min_iters))
    return fail("--min-iters must be a positive integer, got '" +
                cli.min_iters + "'");

  // Absolute, existing ELF (QEMU's -bios resolves relative paths against its
  // data dir, not the CWD) -- the same up-front check run's abs_elf does.
  std::error_code ec;
  const fs::path abs = fs::absolute(cli.positional[0], ec);
  if (ec || !fs::is_regular_file(abs))
    return fail("ELF not found: " + cli.positional[0]);
  const std::string elf = abs.string();

  // The engine pick: exactly hybrid's -- --engine or the sole cycle-accurate
  // engine, with the same errors (naming the discovered candidates).
  Discovery disc = discover_engines();
  std::string err;
  const EngineDescriptor* acc =
      resolve_accurate_engine(disc.engines, cli.engine, err);
  if (!acc) {
    std::fprintf(stderr, "andesim profile: %s\n", err.c_str());
    for (const std::string& w : disc.warnings)
      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
    return 2;
  }
  if (std::string e = elf_engine_arch_error(elf, *acc); !e.empty())
    return fail(e);

  // QEMU follows the engine's width (the arch guard above already pinned the
  // ELF to it; an unreadable ELF falls back to the ELF's own class, then 64).
  const int elf_w = elf_xlen(elf);
  const int xlen = acc->xlen ? static_cast<int>(acc->xlen)
                             : (elf_w ? elf_w : 64);
  const EngineDescriptor qemu = builtin_qemu_arch(xlen);
  const std::string plugin = profile_plugin_path().string();

  Workdir wd;
  if (wd.path.empty()) return fail(wd.error);

  // engine -> QEMU cfg, the same probe + staging the hybrid fast leg uses.
  // "" cfg = tolerant fallback (family-default -cpu), but SAY so: matching
  // the engine's ISA is the whole point of profiling through an engine.
  const RunResult probe =
      run_process({acc->bin_path, "--print-qemu-config"}, 5000);
  const std::string cfg = stage_qemu_cfg(wd.path, probe);
  std::string cpu_model = cfg.empty() ? std::string() : qemu_cpu_from_cfg(probe.out);
  if (cpu_model.empty()) cpu_model = "andes-ax45mpv";
  if (cfg.empty())
    log_line(kLogWarn,
             "[andesim] profile: engine %s gave no --print-qemu-config; "
             "falling back to -cpu %s (the profiled ISA may not match the "
             "engine)",
             acc->id.c_str(), cpu_model.c_str());

  ProfileQemuArgs qa;
  qa.qemu_bin = qemu.bin_path;
  qa.plugin_so = plugin;
  qa.log_path = wd.path + "/plugin.log";
  qa.limit = limit;
  qa.min_iters = min_iters;
  qa.cpu = cpu_model + ",vlen=" + std::to_string(synced_vlen(acc->vlen));
  qa.mem_size = cli.mem_size;  // forwarded as plain -m; QEMU validates it
  qa.readconfig = cfg;
  qa.elf = elf;
  qa.passthrough = cli.passthrough;
  const std::vector<std::string> argv = profile_qemu_argv(qa);

  if (cli.dry_run)
    return print_dry_run({argv}, {"profile [" + acc->id + "]"});

  log_line(kLogDebug, "[andesim] profile engine=%s cpu=%s fixture=%s",
           acc->id.c_str(), qa.cpu.c_str(), abs.stem().string().c_str());

  // Spawn-time checks, AFTER --dry-run so the preview needs no built QEMU.
  if (!fs::is_regular_file(qemu.bin_path) ||
      ::access(qemu.bin_path.c_str(), X_OK) != 0)
    return fail("qemu not found/executable: " + qemu.bin_path +
                " (set QEMU_BIN_DIR in config.env, or source ./setup.sh)");
  if (!fs::is_regular_file(plugin))
    return fail("plugin not built: " + plugin + " (make -C qemu_plugin)");

  log_line(kLogTrace, "[andesim] exec profile [%s]: %s", acc->id.c_str(),
           render_argv(argv).c_str());
  const int rc = exec_passthrough(argv);
  if (rc == -1) return fail("failed to spawn " + qemu.bin_path);
  if (rc != 0)
    log_line(kLogWarn,
             "[andesim] profile: qemu exited rc=%d; the report covers what "
             "ran",
             rc);

  std::string log_text;
  {
    std::ifstream f(qa.log_path);
    std::stringstream ss;
    ss << f.rdbuf();
    log_text = ss.str();
  }

  if (cli.raw) {
    std::fputs(log_text.c_str(), stdout);
    return 0;
  }

  auto all_rows = parse_plugin_log(log_text);
  if (all_rows.empty()) {
    std::fprintf(stderr, "andesim profile: no backward edges observed\n");
    return 0;
  }
  uint64_t total_iters = 0;
  for (const auto& r : all_rows) total_iters += r.iters;

  // Disassembly (the RVV filter + the report's rvv/calls sections need it).
  const std::string objdump = resolve_objdump(cli.objdump);
  Disasm disasm;
  if (!objdump.empty() && (cli.optimize_rvv || cli.llm))
    disasm = parse_disasm(
        run_process({objdump, "-d", "--no-show-raw-insn", elf}, 60000).out);
  if (objdump.empty() && cli.optimize_rvv)
    log_line(kLogWarn,
             "[andesim] profile: no objdump found; the RVV filter drops "
             "every loop -- install a riscv objdump or pass "
             "--no-optimize-rvv");

  auto rows = filter_loops(all_rows, min_iters, cli.optimize_rvv, disasm,
                           limit);
  if (rows.empty()) {
    std::fprintf(stderr, "andesim profile: no loops with iters >= %d%s\n",
                 min_iters,
                 cli.optimize_rvv ? " containing RVV instructions" : "");
    return 0;
  }

  // Source resolution (addr2line), unless --no-source.
  std::map<uint64_t, std::string> src_map;
  if (!cli.no_source) {
    const std::string a2l = !cli.addr2line.empty()
                                ? cli.addr2line
                                : find_first({"llvm-addr2line", "addr2line",
                                              "riscv64-unknown-elf-addr2line",
                                              "riscv32-unknown-elf-addr2line",
                                              "riscv64-linux-gnu-addr2line"});
    std::vector<uint64_t> pcs;
    for (const auto& r : rows) {
      pcs.push_back(r.start);
      pcs.push_back(r.end);
    }
    std::sort(pcs.begin(), pcs.end());
    pcs.erase(std::unique(pcs.begin(), pcs.end()), pcs.end());
    src_map = resolve_sources(a2l, elf, pcs);
  }

  std::string report;
  if (cli.llm) {
    const auto loops = build_loops(rows, limit);
    std::vector<LoopSyms> syms;
    syms.reserve(loops.size());
    for (const auto& l : loops)
      syms.push_back(make_syms(elf, l.start, l.end, src_map));
    report = render_llm(loops, syms, total_iters, abs.filename().string(),
                        disasm, min_iters, cli.optimize_rvv);
  } else {
    std::vector<LoopSyms> syms;
    syms.reserve(rows.size());
    for (const auto& r : rows)
      syms.push_back(make_syms(elf, r.start, r.end, src_map));
    report = render_table(rows, syms, min_iters, cli.optimize_rvv);
  }
  std::fputs(report.c_str(), stdout);
  return 0;
}

}  // namespace andes_sim

