19	// printf-append onto a std::string (the renderers' one formatting primitive).
20	#if defined(__GNUC__)
21	__attribute__((format(printf, 2, 3)))
22	#endif
23	void appendf(std::string& out, const char* fmt, ...) {
24	  va_list ap;
25	  va_start(ap, fmt);
26	  va_list ap2;
27	  va_copy(ap2, ap);
28	  int n = vsnprintf(nullptr, 0, fmt, ap);
29	  va_end(ap);
30	  if (n < 0) {
31	    va_end(ap2);
32	    return;
33	  }
34	  std::string buf(static_cast<size_t>(n) + 1, '\0');
35	  vsnprintf(buf.data(), buf.size(), fmt, ap2);
36	  va_end(ap2);
37	  buf.resize(static_cast<size_t>(n));
38	  out += buf;
39	}
40	
41	const std::set<std::string> kCallMnemonics = {"jal", "jalr", "c.jal", "c.jalr"};
42	
43	}  // namespace
44	
45	std::vector<LoopEdge> parse_plugin_log(const std::string& text) {
46	  std::vector<LoopEdge> rows;
47	  static const std::regex re(
48	      R"(\s*(0x[0-9a-fA-F]+)\s*,\s*(0x[0-9a-fA-F]+)\s*,\s*(\d+))");
49	  std::istringstream ss(text);
50	  std::string line;
51	  while (std::getline(ss, line)) {
52	    std::smatch m;
53	    if (!std::regex_search(line, m, re)) continue;
54	    rows.push_back({std::stoull(m[1], nullptr, 16),
55	                    std::stoull(m[2], nullptr, 16), std::stoull(m[3])});
56	  }
57	  return rows;
58	}
59	
60	Disasm parse_disasm(const std::string& raw) {
61	  Disasm m;
62	  std::istringstream ss(raw);
63	  // Matches: optional leading whitespace, hex digits, colon, whitespace,
64	  // then mnemonic. Works for both GNU and LLVM objdump.
65	  static const std::regex re(R"(^\s*([0-9a-fA-F]+):\s+(\S+)(?:\s+(.*))?$)");
66	  std::string line;
67	  while (std::getline(ss, line)) {
68	    while (!line.empty() && (line.back() == '\r' || line.back() == '\n'))
69	      line.pop_back();
70	    std::smatch sm;
71	    if (!std::regex_match(line, sm, re)) continue;
72	    uint64_t pc;
73	    try {
74	      pc = std::stoull(sm[1], nullptr, 16);
75	    } catch (...) {
76	      continue;
77	    }
78	    std::string mn = sm[2];
79	    std::string ops = sm.size() > 3 ? sm[3].str() : "";
80	    while (!ops.empty() && (ops.back() == ' ' || ops.back() == '\t'))
81	      ops.pop_back();
82	    m[pc] = {std::move(mn), std::move(ops)};
83	  }
84	  return m;
85	}
86	
87	bool is_rvv(const std::string& mnemonic) {
88	  if (mnemonic.size() < 2) return false;
89	  char lo = static_cast<char>(
90	      tolower(static_cast<unsigned char>(mnemonic[0])));
91	  return lo == 'v' && std::isalpha(static_cast<unsigned char>(mnemonic[1]));
92	}
93	
94	std::vector<RvvInsn> rvv_in_range(const Disasm& disasm, uint64_t s,
95	                                  uint64_t e) {
96	  std::vector<RvvInsn> out;
97	  auto it = disasm.lower_bound(s);
98	  while (it != disasm.end() && it->first <= e) {
99	    if (is_rvv(it->second.mnemonic))
100	      out.push_back({it->first, it->second.mnemonic, it->second.operands});
101	    ++it;
102	  }
103	  return out;
104	}
105	
106	std::vector<CallInsn> calls_in_range(const Disasm& disasm, uint64_t s,
107	                                     uint64_t e) {
108	  std::vector<CallInsn> out;
109	  static const std::regex callee_re("<([^>]+)>");
110	  auto it = disasm.lower_bound(s);
111	  while (it != disasm.end() && it->first <= e) {
112	    std::string lo = it->second.mnemonic;
113	    std::transform(lo.begin(), lo.end(), lo.begin(),
114	                   [](unsigned char c) { return tolower(c); });
115	    if (kCallMnemonics.count(lo)) {
116	      std::smatch m;
117	      std::string target = "(indirect)";
118	      if (std::regex_search(it->second.operands, m, callee_re)) target = m[1];
119	      out.push_back({it->first, it->second.mnemonic, target});
120	    }
121	    ++it;
122	  }
123	  return out;
124	}
125	
126	std::vector<LoopEdge> filter_loops(std::vector<LoopEdge> rows, int min_iters,
127	                                   bool rvv_only, const Disasm& disasm,
128	                                   int limit) {
129	  rows.erase(std::remove_if(rows.begin(), rows.end(),
130	                            [&](const LoopEdge& r) {
131	                              return r.iters <
132	                                     static_cast<uint64_t>(min_iters);
133	                            }),
134	             rows.end());
135	  if (rvv_only) {
136	    rows.erase(std::remove_if(rows.begin(), rows.end(),
137	                              [&](const LoopEdge& r) {
138	                                return rvv_in_range(disasm, r.start, r.end)
139	                                    .empty();
140	                              }),
141	               rows.end());
142	  }
143	  std::sort(rows.begin(), rows.end(),
144	            [](const LoopEdge& a, const LoopEdge& b) {
145	              return a.iters > b.iters;
146	            });
147	  if (static_cast<int>(rows.size()) > limit)
148	    rows.resize(static_cast<size_t>(limit));
149	  return rows;
150	}
151	
152	std::vector<Loop> build_loops(const std::vector<LoopEdge>& rows, int limit) {
153	  std::vector<Loop> loops;
154	  int n = std::min(static_cast<int>(rows.size()), limit);
155	  loops.reserve(static_cast<size_t>(n));
156	  for (int i = 0; i < n; ++i)
157	    loops.push_back({"L" + std::to_string(i + 1),
158	                     rows[static_cast<size_t>(i)].start,
159	                     rows[static_cast<size_t>(i)].end,
160	                     rows[static_cast<size_t>(i)].iters,
161	                     -1,
162	                     {}});
163	
164	  // Parent: the smallest enclosing range; identical ranges never nest.
165	  for (int i = 0; i < n; ++i) {
166	    int best = -1;
167	    uint64_t best_sz = UINT64_MAX;
168	    for (int j = 0; j < n; ++j) {
169	      if (j == i) continue;
170	      if (loops[j].start == loops[i].start && loops[j].end == loops[i].end)
171	        continue;
172	      if (loops[j].start <= loops[i].start && loops[i].end <= loops[j].end) {
173	        uint64_t sz = loops[j].end - loops[j].start;
174	        if (sz < best_sz) {
175	          best = j;
176	          best_sz = sz;
177	        }
178	      }
179	    }
180	    loops[static_cast<size_t>(i)].parent = best;
181	  }
182	  for (int i = 0; i < n; ++i)
183	    if (loops[static_cast<size_t>(i)].parent >= 0)
184	      loops[static_cast<size_t>(loops[static_cast<size_t>(i)].parent)]
185	          .children.push_back(i);
186	
187	  return loops;
188	}
189	
190	uint64_t measure_ret_pc(const Disasm& disasm, uint64_t fn_entry,
191	                        uint64_t fn_end) {
192	  uint64_t ret_pc = fn_end - 4;  // safe default (standard ret is 4 bytes)
193	  auto it = disasm.lower_bound(fn_end);
194	  if (it != disasm.begin()) {
195	    --it;
196	    if (it->first >= fn_entry) ret_pc = it->first;
197	  }
198	  return ret_pc;
199	}
200	
201	std::string src_basename(const std::string& s) {
202	  if (s.empty()) return "";
203	  // "path:line[ (extra)]" -> "basename(path):line[ ...]"
204	  auto sp = s.find(' ');
205	  std::string head = (sp != std::string::npos) ? s.substr(0, sp) : s;
206	  std::string tail = (sp != std::string::npos) ? s.substr(sp) : "";
207	  auto slash = head.rfind('/');
208	  return ((slash != std::string::npos) ? head.substr(slash + 1) : head) + tail;
209	}
210	
211	std::pair<std::string, int> parse_file_line(const std::string& s) {
212	  if (s.empty() || s.rfind("??", 0) == 0) return {"", 0};
213	  static const std::regex re(R"(^(.+?):(\d+)(?::\d+)?(?:\s|$))");
214	  std::smatch m;
215	  if (!std::regex_search(s, m, re)) return {"", 0};
216	  return {m[1], std::stoi(m[2])};
217	}
