418	    if (have_src)
419	      appendf(out, "%*llu | 0x%016llx -> 0x%016llx | %-*s | %s\n",
420	              static_cast<int>(w_iter), (unsigned long long)r.iters,
421	              (unsigned long long)r.start, (unsigned long long)r.end,
422	              static_cast<int>(w_sym), loc.c_str(), srcpair(syms[i]).c_str());
423	    else
424	      appendf(out, "%*llu | 0x%016llx -> 0x%016llx | %s\n",
425	              static_cast<int>(w_iter), (unsigned long long)r.iters,
426	              (unsigned long long)r.start, (unsigned long long)r.end,
427	              loc.c_str());
428	  }
429	  return out;
430	}
