3	namespace andes_sim {
4	namespace {
5	
6	// Try to read an option's value at args[i]. Supports both `--flag value`
7	// (consumes the next token, advancing i) and `--flag=value`.
8	//   returns  1 = matched, `out` set
9	//            0 = this token is not `flag`
10	//           -1 = matched `--flag` but no value follows
11	int match_opt(const std::vector<std::string>& args, size_t& i,
12	              const std::string& flag, std::string& out) {
13	  const std::string& a = args[i];
14	  if (a == flag) {
15	    if (i + 1 >= args.size()) return -1;
16	    out = args[++i];
17	    return 1;
18	  }
19	  const std::string pfx = flag + "=";
20	  if (a.starts_with(pfx)) {
21	    out = a.substr(pfx.size());
22	    return 1;
23	  }
24	  return 0;
25	}
26	
27	}  // namespace
28	
29	bool is_subcommand(std::string_view name) {
30	  return name == "run" || name == "list" || name == "doctor" ||
31	         name == "profile";
32	}
33	
34	Cli parse_cli(const std::vector<std::string>& args) {
35	  Cli c;
36	  if (args.empty()) return c;  // no subcommand; caller prints usage
37	
38	  // First token is the subcommand, unless it is a top-level help request.
39	  if (args[0] == "-h" || args[0] == "--help") {
40	    c.help = true;
41	    return c;
42	  }
43	
44	  // `run` is the default command: any other first token is `run`'s own
45	  // first argument (a flag or the ELF), not a subcommand.
46	  size_t first = 1;
47	  if (is_subcommand(args[0])) {
48	    c.subcommand = args[0];
49	  } else {
50	    c.subcommand = "run";
51	    first = 0;
52	  }
53	
54	  for (size_t i = first; i < args.size(); ++i) {
55	    const std::string& a = args[i];
