1	// Unit tests for the andesim CLI parser (parse_cli).
2	//
3	// Plain assert-and-count harness (no doctest dependency on the driver side).
4	// Exits non-zero if any check fails. Run by tests/andes_sim/test_andes_sim_f1.sh
5	// and, later, the F5+ infra tests.
6	#include <string>
7	#include <vector>
8	
9	#include "cli.hpp"
10	#include "test_check.hpp"
11	
12	using andes_sim::Cli;
13	using andes_sim::parse_cli;
14	
15	int main() {
16	  // Selection axes, space-separated form.
17	  {
18	    Cli c = parse_cli({"run", "--mode", "fast", "--engine",
19	                       "vsim:ax45mpv_premium", "--trigger", "marker",
20	                       "prog.elf"});
21	    CHECK(c.error.empty());
22	    CHECK(c.subcommand == "run");
23	    CHECK(c.model == "fast");
24	    CHECK(c.engine == "vsim:ax45mpv_premium");
25	    CHECK(c.trigger == "marker");
26	    CHECK(c.positional.size() == 1 && c.positional[0] == "prog.elf");
27	    CHECK(!c.has_passthrough);
28	    CHECK(c.passthrough.empty());
29	  }
30	
31	  // Selection axes, --flag=value form.
32	  {
33	    Cli c = parse_cli({"run", "--mode=cycle", "--engine=vsim:x"});
34	    CHECK(c.error.empty());
35	    CHECK(c.model == "cycle");
36	    CHECK(c.engine == "vsim:x");
37	  }
38	
39	  // The `--` boundary: everything after it is verbatim passthrough, even
40	  // tokens that look like framework flags (they must NOT be parsed).
41	  {
42	    Cli c = parse_cli({"run", "--mode", "fast", "prog.elf", "--", "-gdb",
43	                       "tcp::1234", "-S", "--mode", "IGNORED"});
44	    CHECK(c.error.empty());
45	    CHECK(c.model == "fast");
46	    CHECK(c.positional.size() == 1 && c.positional[0] == "prog.elf");
47	    CHECK(c.has_passthrough);
48	    CHECK(c.passthrough.size() == 5);
49	    CHECK(c.passthrough[0] == "-gdb");
50	    CHECK(c.passthrough[1] == "tcp::1234");
51	    CHECK(c.passthrough[4] == "IGNORED");
52	  }
53	
54	  // A `--` with nothing after it still marks passthrough (empty argv).
55	  {
56	    Cli c = parse_cli({"run", "--mode", "fast", "--"});
57	    CHECK(c.error.empty());
58	    CHECK(c.has_passthrough);
59	    CHECK(c.passthrough.empty());
60	  }
61	
62	  // Per-subcommand help.
63	  {
64	    Cli c = parse_cli({"run", "-h"});
65	    CHECK(c.subcommand == "run");
66	    CHECK(c.help);
67	  }
68	  {
69	    Cli c = parse_cli({"list", "--help"});
70	    CHECK(c.subcommand == "list");
71	    CHECK(c.help);
72	  }
73	
74	  // Top-level help: no subcommand.
75	  {
76	    Cli c = parse_cli({"-h"});
77	    CHECK(c.subcommand.empty());
78	    CHECK(c.help);
79	  }
80	
81	  // list positional target.
82	  {
83	    Cli c = parse_cli({"list", "fixtures"});
84	    CHECK(c.subcommand == "list");
85	    CHECK(c.positional.size() == 1 && c.positional[0] == "fixtures");
86	  }
87	
88	  // Hybrid pc-trigger boundaries (symbol + 0x address), space-separated form.
89	  {
90	    Cli c = parse_cli({"run", "--mode", "hybrid", "--trigger", "pc",
91	                       "--pc-start", "main", "--pc-end", "0x80001234",
92	                       "prog.elf"});
93	    CHECK(c.error.empty());
94	    CHECK(c.pc_start == "main");
95	    CHECK(c.pc_end == "0x80001234");
96	    CHECK(c.positional.size() == 1 && c.positional[0] == "prog.elf");
97	  }
98	
99	  // Hybrid mem size; mixes space and =forms.
100	  // --mmap-size is the retired spelling, kept as a hidden alias of --mem-size.
101	  {
102	    Cli c = parse_cli({"run", "--mode", "hybrid", "--trigger", "marker",
103	                       "--mmap-size=64M", "prog.elf"});
104	    CHECK(c.error.empty());
105	    CHECK(c.mem_size == "64M");
106	  }
107	
108	  // The icount/warmup knobs were removed: --qemu-icount / --vsim-icount /
109	  // --vsim-warmup-icount are now unknown options.
110	  {
111	    Cli c = parse_cli({"run", "--mode", "hybrid", "--qemu-icount", "10",
112	                       "prog.elf"});
113	    CHECK(!c.error.empty());
114	    Cli d = parse_cli({"run", "--mode", "hybrid", "--vsim-icount", "10",
115	                       "prog.elf"});
116	    CHECK(!d.error.empty());
117	    Cli e = parse_cli({"run", "--mode", "hybrid", "--vsim-warmup-icount", "500",
118	                       "prog.elf"});
119	    CHECK(!e.error.empty());
120	  }
121	
122	  // --what was a placeholder for a never-wired `build` subcommand: it parsed
123	  // but no command read it, so it silently swallowed its value everywhere.
124	  // Removed -- now an unknown option like any other.
125	  {
126	    Cli c = parse_cli({"run", "--mode", "fast", "--what", "driver", "prog.elf"});
127	    CHECK(!c.error.empty());
128	  }
129	
130	  // --mem-size is the documented spelling (works on every model).
131	  {
132	    Cli c = parse_cli({"run", "--mode", "fast", "--mem-size", "2G",
133	                       "prog.elf"});
134	    CHECK(c.error.empty());
135	    CHECK(c.mem_size == "2G");
136	  }
137	
138	  // Absent hybrid flags stay empty -- cmd_run supplies the real defaults.
139	  {
140	    Cli c = parse_cli({"run", "--mode", "hybrid", "prog.elf"});
141	    CHECK(c.error.empty());
142	    CHECK(c.pc_start.empty());
143	    CHECK(c.mem_size.empty());
144	  }
145	
146	  // kanata/objdump pass-through flags parse like the rest (space + =form).
147	  {
148	    Cli c = parse_cli({"run", "--mode", "hybrid", "--kanata", "k.txt",
149	                       "--objdump=o.txt", "prog.elf"});
150	    CHECK(c.error.empty());
151	    CHECK(c.kanata == "k.txt");
152	    CHECK(c.objdump == "o.txt");
153	  }
154	
155	  // --verify is a boolean (oracle differential verification), default off.
156	  {
157	    Cli c = parse_cli({"run", "--mode", "hybrid", "--verify", "prog.elf"});
158	    CHECK(c.error.empty());
159	    CHECK(c.verify);
160	    CHECK(c.positional.size() == 1 && c.positional[0] == "prog.elf");
161	    Cli d = parse_cli({"run", "--mode", "hybrid", "prog.elf"});
162	    CHECK(!d.verify);
163	  }
164	
165	  // --print-memmap is a boolean (print the hybrid guest memory map and
166	  // exit), default off; the ELF stays optional for it (cmd_run's rule).
167	  {
168	    Cli c = parse_cli({"run", "--mode", "hybrid", "--print-memmap"});
169	    CHECK(c.error.empty());
170	    CHECK(c.print_memmap);
171	    CHECK(c.positional.empty());
172	    Cli d = parse_cli({"run", "--mode", "hybrid", "prog.elf"});
173	    CHECK(!d.print_memmap);
174	  }
175	
176	  // --gdb is a boolean, default off; valid on fast and cycle.
177	  {
178	    Cli c = parse_cli({"run", "--mode", "fast", "--gdb", "prog.elf"});
179	    CHECK(c.error.empty());
180	    CHECK(c.gdb);
181	    CHECK(c.positional.size() == 1 && c.positional[0] == "prog.elf");
182	    Cli d = parse_cli({"run", "--mode", "cycle", "prog.elf"});
183	    CHECK(!d.gdb);
184	  }
185	
186	  // `run` is the default command: a first token that is not a known
187	  // subcommand parses exactly like `run ...` -- flag-first form.
188	  {
189	    Cli c = parse_cli({"--mode", "fast", "prog.elf"});
190	    CHECK(c.error.empty());
191	    CHECK(c.subcommand == "run");
192	    CHECK(c.model == "fast");
193	    CHECK(c.positional.size() == 1 && c.positional[0] == "prog.elf");
194	  }
195	
196	  // ... and ELF-first form.
197	  {
198	    Cli c = parse_cli({"prog.elf", "--mode", "fast"});
199	    CHECK(c.error.empty());
200	    CHECK(c.subcommand == "run");
201	    CHECK(c.model == "fast");
202	    CHECK(c.positional.size() == 1 && c.positional[0] == "prog.elf");
203	  }
204	
205	  // The implicit form still honors the `--` passthrough boundary.
206	  {
207	    Cli c = parse_cli({"--mode", "fast", "prog.elf", "--", "-S"});
208	    CHECK(c.error.empty());
209	    CHECK(c.subcommand == "run");
210	    CHECK(c.has_passthrough);
211	    CHECK(c.passthrough.size() == 1 && c.passthrough[0] == "-S");
212	  }
213	
214	  // Explicit subcommands are untouched by the default: `list`/`doctor`
215	  // first tokens stay subcommands, not positionals.
216	  {
217	    Cli c = parse_cli({"doctor"});
218	    CHECK(c.subcommand == "doctor");
219	    CHECK(c.positional.empty());
220	  }
221	
222	  // --log-level parses like the other value options (space + =form) and
223	  // defaults to empty (cmd dispatch applies the real default, info).
224	  {
225	    Cli c = parse_cli({"run", "--mode", "fast", "--log-level", "1", "prog.elf"});
226	    CHECK(c.error.empty());
227	    CHECK(c.log_level == "1");
228	    Cli d = parse_cli({"--log-level=4", "--mode", "fast", "prog.elf"});
229	    CHECK(d.error.empty());
230	    CHECK(d.log_level == "4");
231	    CHECK(d.subcommand == "run");
232	    Cli e = parse_cli({"run", "--mode", "fast", "prog.elf"});
233	    CHECK(e.log_level.empty());
234	  }
235	
236	  // Unknown option before `--` is an error.
237	  {
238	    Cli c = parse_cli({"run", "--bogus"});
239	    CHECK(!c.error.empty());
240	  }
241	
242	  // A selection flag with no value is an error.
243	  {
244	    Cli c = parse_cli({"run", "--mode"});
245	    CHECK(!c.error.empty());
246	  }
247	
248	  // --model was renamed to --mode (clean break): the old spelling no longer
249	  // parses -- it falls through to the unknown-option error.
250	  {
251	    Cli c = parse_cli({"run", "--model", "fast", "prog.elf"});
252	    CHECK(!c.error.empty());
253	  }
254	
255	  // `profile` is a subcommand: it must NOT be swallowed by the default-run
256	  // rule (which would make it run's ELF positional).
257	  {
258	    Cli c = parse_cli({"profile", "prog.elf"});
259	    CHECK(c.error.empty());
260	    CHECK(c.subcommand == "profile");
